       "html": "<img class=\"formula\" src=\"../media/formulak/88d6b53f8f56a8d1.svg\" alt=\"mat(row-gap: #6pt, column-gap: #9pt, augment: #2, 1,m,m - 1; m,1,2 - 2m)\" style=\"width:7.659em;height:1.579em\" loading=\"lazy\">"
